#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by spark/ring/mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enp1s0f0np0 | grep clsact >/dev/null || tc qdisc add dev enp1s0f0np0 clsact
tc qdisc show dev enp1s0f1np1 | grep clsact >/dev/null || tc qdisc add dev enp1s0f1np1 clsact
tc filter show dev enp1s0f1np1 ingress pref 49156 | grep flower >/dev/null || tc filter add dev enp1s0f1np1 ingress protocol 0x88b5 pref 49156 handle 49156 flower skip_sw src_mac 4c:bb:47:80:f3:29 dst_mac 4c:bb:47:80:b2:0d action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:ab:af pipe action mirred egress redirect dev enp1s0f0np0
tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep in_hw >/dev/null || { echo 'rule pref 49156 on enp1s0f1np1 is not in hardware'; exit 3; }
tc filter show dev enp1s0f0np0 ingress pref 49166 | grep flower >/dev/null || tc filter add dev enp1s0f0np0 ingress protocol 0x88b5 pref 49166 handle 49166 flower skip_sw src_mac 4c:bb:47:80:ab:af dst_mac 4c:bb:47:80:b2:0c action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:f3:29 pipe action mirred egress redirect dev enp1s0f1np1
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep in_hw >/dev/null || { echo 'rule pref 49166 on enp1s0f0np0 is not in hardware'; exit 3; }
ip route show exact 10.100.241.14/32 | grep . >/dev/null || ip route add 10.100.241.14/32 via 10.100.241.10 dev enP2p1s0f0np0 src 10.100.241.9
ip route show exact 10.251.20.1/32 | grep . >/dev/null || ip route add 10.251.20.1/32 via 10.251.20.5 dev enp1s0f1np1 src 10.251.20.6
for d in roceP2p1s0f0 rocep1s0f1; do systemctl start spark-ring-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f0 rocep1s0f1; do systemctl is-active --quiet spark-ring-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
